css='''
:root{--bg:#08111f;--panel:#0e2038;--line:rgba(255,255,255,.1);--txt:#eef6ff;--mut:#aabbd2;--blue:#5bbcff;--green:#22c55e;--yellow:#ffd166;--red:#fb7185}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,#173a63,#08111f 58%);color:var(--txt);font-family:Inter,system-ui,Segoe UI,Arial,sans-serif;font-size:14px;line-height:1.55}a{color:#8ed6ff;text-decoration:none}.feiq-language-switcher{position:sticky;top:0;z-index:9999;display:flex;justify-content:flex-end;gap:8px;padding:8px 14px;background:rgba(7,16,29,.92);backdrop-filter:blur(8px);border-bottom:1px solid rgba(255,255,255,.08)}.feiq-language-switcher a{color:#d8f1ff;border:1px solid rgba(91,188,255,.35);border-radius:999px;padding:5px 10px;font-size:12px;font-weight:900;background:rgba(91,188,255,.08)}header,main{max-width:1220px;margin:0 auto;padding:24px}.topnav{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:24px}.brand{font-weight:950;font-size:19px;color:#fff}.brand span{color:var(--blue)}.navlinks{display:flex;gap:14px;color:var(--mut);font-size:13px}h1{margin:0 0 10px;font-size:clamp(32px,5vw,56px);letter-spacing:-.055em;line-height:1}.sub{color:var(--mut);font-size:17px;max-width:980px}.note{background:rgba(255,209,102,.08);border:1px solid rgba(255,209,102,.25);border-radius:16px;padding:14px;color:#ffe8a3;margin:18px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;margin:18px 0}.card{background:rgba(14,32,56,.9);border:1px solid var(--line);border-radius:18px;padding:16px;box-shadow:0 16px 50px rgba(0,0,0,.18)}.card h3{margin:0 0 12px}.row{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.07)}.row:last-child{border-bottom:0}.row span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.row b{color:#fff}.downloads{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.btn,button{display:inline-flex;background:#143052;color:#fff;border:1px solid rgba(91,188,255,.24);border-radius:12px;padding:10px 13px;font-weight:850;cursor:pointer}input{background:#0b1b30;border:1px solid rgba(255,255,255,.12);color:#eef6ff;border-radius:12px;padding:10px 12px;min-width:260px}.tablewrap{overflow:auto;max-height:72vh;border:1px solid var(--line);border-radius:16px;background:#0b1b30}table{border-collapse:separate;border-spacing:0;min-width:1100px;width:100%;font-size:12px}th,td{padding:9px 10px;border-bottom:1px solid rgba(255,255,255,.08);white-space:nowrap;text-align:left}th{position:sticky;top:0;background:#193b63;color:#fff;z-index:3;cursor:pointer}td:first-child,th:first-child{position:sticky;left:0;background:#0b1b30;z-index:2}th:first-child{z-index:4;background:#193b63}.good{color:#86efac;font-weight:900}.warn{color:#fde68a;font-weight:900}.bad{color:#fda4af;font-weight:900}.mut{color:var(--mut)}footer{max-width:1220px;margin:0 auto;padding:12px 24px 32px;color:var(--mut);font-size:13px;border-top:1px solid var(--line)}@media(max-width:760px){header,main{padding-left:14px;padding-right:14px}.navlinks{display:none}input{width:100%;min-width:0}.feiq-language-switcher{justify-content:center}}
'''

def page(lang,cfg,filename):
    en=SITE+'/euroleague/defense-vs-position'; sr=SITE+'/sr/euroleague/defense-vs-position'; el=SITE+'/el/euroleague/defense-vs-position'
    canonical=SITE+cfg['route']
    nav=''.join(f'<a href="{href}">{html.escape(label)}</a>' for label,href in cfg['nav'])
    langbar='<div class="feiq-language-switcher"><a href="/euroleague/defense-vs-position">EN</a><a href="/sr/euroleague/defense-vs-position">SR</a><a href="/el/euroleague/defense-vs-position">EL</a></div>'
    script=f"""const DATA={{summary:{json.dumps(rows,separators=(',',':'))}}};const COLS={json.dumps(cols,separators=(',',':'))};const LABELS={json.dumps(cfg['col'],ensure_ascii=False,separators=(',',':'))};let sort={{c:'guard_pts_allowed_pg',d:'desc'}};function fmt(v){{if(v===null||v===undefined)return ''; if(typeof v==='boolean')return v?'Yes':'No'; let n=Number(v); if(Number.isFinite(n))return Math.abs(n)>=100?String(Math.round(n*10)/10):String(Math.round(n*100)/100); return String(v)}}function cls(c,v){{if(c.includes('fdr')){{let n=Number(v);return n<=2.25?'good':n>=3.75?'bad':'warn'}} if(c==='validation_ok')return v?'good':'bad'; return ''}}function cmp(a,b,c){{let av=a[c],bv=b[c],an=Number(av),bn=Number(bv),r;if(av==null&&bv==null)r=0;else if(av==null)r=1;else if(bv==null)r=-1;else if(Number.isFinite(an)&&Number.isFinite(bn))r=an-bn;else r=String(av).localeCompare(String(bv));return sort.d==='asc'?r:-r}}function setSort(c){{sort={{c,d:sort.c===c&&sort.d==='desc'?'asc':'desc'}};render()}}function render(){{let rows=DATA.summary.filter(r=>!q.value||Object.values(r).join(' ').toLowerCase().includes(q.value.toLowerCase())).sort((a,b)=>cmp(a,b,sort.c));tbl.innerHTML='<thead><tr>'+COLS.map(c=>`<th onclick="setSort('${{c}}')">${{LABELS[c]||c}}${{sort.c===c?(sort.d==='asc'?' ↑':' ↓'):''}}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+COLS.map(c=>`<td class="${{cls(c,r[c])}}">${{fmt(r[c])}}</td>`).join('')+'</tr>').join('')+'</tbody>'}}function mini(id,col){{let rows=[...DATA.summary].sort((a,b)=>(Number(b[col])||0)-(Number(a[col])||0)).slice(0,6);document.getElementById(id).innerHTML=rows.map(r=>`<div class='row'><span>${{r.team_abbr}} <span class='mut'>${{r.team_name||''}}</span></span><b>${{fmt(r[col])}}</b></div>`).join('')}}mini('guardBox','guard_pts_allowed_pg');mini('forwardBox','forward_pts_allowed_pg');mini('centerBox','center_pts_allowed_pg');render();"""
    doc=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(cfg['title'])} - Fantasy Edge IQ</title><meta name="description" content="{html.escape(cfg['desc'])}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="{en}"><link rel="alternate" hreflang="sr" href="{sr}"><link rel="alternate" hreflang="el" href="{el}"><link rel="alternate" hreflang="x-default" href="{en}"><meta name="robots" content="index,follow"><script defer src="/_vercel/insights/script.js"></script><style>{css}</style><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><meta name="theme-color" content="#07101d"><meta property="og:image" content="{SITE}/og-image.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{SITE}/og-image.png"></head><body>{langbar}<header><div class="topnav"><a class="brand" href="{cfg['brand_home']}">Fantasy Edge <span>IQ</span></a><nav class="navlinks">{nav}</nav></div><h1>{html.escape(cfg['title'])}</h1><div class="sub">{html.escape(cfg['sub'])}</div></header><main><div class="note"><b>Info:</b> {html.escape(cfg['note'])}</div><div class="downloads"><a class="btn" href="/euroleague-defense-vs-position.csv">{html.escape(cfg['download'])}</a><a class="btn" href="/euroleague-defense-vs-position-matchlog.csv">{html.escape(cfg['matchlog'])}</a><a class="btn" href="/euroleague">{html.escape(cfg['back'])}</a></div><section class="cards"><div class="card"><h3>{html.escape(cfg['cards'][0])}</h3><div id="guardBox"></div></div><div class="card"><h3>{html.escape(cfg['cards'][1])}</h3><div id="forwardBox"></div></div><div class="card"><h3>{html.escape(cfg['cards'][2])}</h3><div id="centerBox"></div></div></section><div class="downloads"><input id="q" placeholder="{html.escape(cfg['search'])}" oninput="render()"></div><div class="tablewrap"><table id="tbl"></table></div></main><footer>{html.escape(cfg['footer'])}</footer><script>{script}</script></body></html>'''
    (ROOT/filename).write_text(doc,encoding='utf-8')

page('en',labels['en'],'euroleague-defense-vs-position.html')
page('sr',labels['sr'],'sr-euroleague-defense-vs-position.html')
page('el',labels['el'],'el-euroleague-defense-vs-position.html')
print('wrote DvP pages')
